export function TracksNew() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.tracks.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/tracks/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New track" actions={<Link href="/tracks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <TracksForm
        fields={TRACKS_CREATE}
        initial={EMPTY_TRACKS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toTracksCreateInput(values))}
      />
    </Pane>
  );
}

/**
 * The genres of a track: the Genre rows TrackGenre links it to. Changes go
 * through track_genres, under its own rules; the names come with the row.
 */
function TracksGenresField({ row, user }: { row: Detail; user: SessionUser | null }) {
  void user;
  const queryClient = useQueryClient();
  const linkInput = { track_id: row.id, page_size: 200 } as Inputs["track_genres"]["list"];
  const links = useQuery({ queryKey: ["track_genres", "list", linkInput], queryFn: () => client.track_genres.list(linkInput) });
  const options = useQuery({ queryKey: ["genres", "list", { page_size: 200 }], queryFn: () => client.genres.list({ page_size: 200 }) });
  const settle = async () => {
    await queryClient.invalidateQueries({ queryKey: ["track_genres"] });
    await queryClient.invalidateQueries({ queryKey: KEY });
  };
  void settle;
  const add = useMutation({ mutationFn: (input: Inputs["track_genres"]["create"]) => client.track_genres.create(input), onSuccess: settle });
  const remove = useMutation({ mutationFn: (input: Inputs["track_genres"]["delete"]) => client.track_genres.delete(input), onSuccess: settle });
  type Link = Outputs["track_genres"]["list"]["data"][number];
  const far = new Map(row.genres.map(item => [text(item.id), item] as const));
  const label = (link: Link) => text(far.get(text(link.genre_id))?.name);
  const items = [...(links.data?.data ?? [])].sort((a, b) => label(a).localeCompare(label(b)));
  const busy = add.isPending || remove.isPending;
  return (
    <div>
      {links.data ? <NameChips items={items} keyOf={link => text(link.id)} label={label} onRemove={user !== null ? link => remove.mutate({ id: link.id }) : undefined} busy={busy} /> : <NameChips items={row.genres} keyOf={item => text(item.id)} label={item => text(item.name)} />}
      {user !== null ? (
        <AddPicker
          options={(options.data?.data ?? []).filter(item => !far.has(text(item.id)))}
          keyOf={item => text(item.id)}
          label={item => text(item.name)}
          placeholder="Add a genre…"
          onAdd={item => add.mutate({ track_id: row.id, genre_id: item.id } as Inputs["track_genres"]["create"])}
          busy={busy}
        />
      ) : null}
      <ErrorNote error={add.error ?? remove.error} className="mt-2" />
    </div>
  );
}

export function TracksDetail() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.tracks.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["tracks"]["update"]) => client.tracks.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["tracks"]["delete"]) => client.tracks.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/tracks");
    }
  });
  const moveAction = useMutation({
    mutationFn: (input: Inputs["tracks"]["move"]) => client.tracks.move(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.title) || "Track " + text(row.id)}
      actions={
        <>
          <Link href="/tracks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canMove(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setOpenAction(open => (open === "move" ? null : "move"))}>
              Move
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this track?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >
      {openAction === "move" ? (
        <div className="mb-6 rounded-md border border-border p-4">
          <TracksMoveForm fields={TRACKSMOVE_CREATE} initial={EMPTY_TRACKSMOVE} submitLabel="Move" pending={moveAction.isPending} error={moveAction.error} onCancel={() => setOpenAction(null)} onSubmit={values => moveAction.mutate({ id, ...toTracksMoveCreateInput(values) })} />
        </div>
      ) : null}

      {editing ? (
        <TracksForm
          fields={TRACKS_UPDATE}
          initial={tracksFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toTracksUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Album">{(row.album ? text(row.album.title) : text(row.album_id)) || "—"}</FieldRow>
        <FieldRow label="Duration Seconds">{text(row.duration_seconds) || "—"}</FieldRow>
        <FieldRow label="Track Number">{text(row.track_number) || "—"}</FieldRow>
        <FieldRow label="Genres">
          <TracksGenresField row={row} user={user} />
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}
